python3 -c '
# Exact regular docs Day 1..9 (depts, count)
docs = {
    1: [("d1-1", {"Fin","Leg"}, 14), ("d1-2", {"Fin","Eng"}, 16)],
    2: [("d2-1", {"Leg","Res"}, 17), ("d2-2", {"Fin","Res"}, 11)],
    3: [("d3-1", {"Fin","Res"}, 11), ("d3-2", {"Eng","Res"}, 19), ("d3-3", {"Leg","Res"}, 17), ("d3-4", {"Eng","Sales"}, 19)],
    4: [("d4-1", {"Leg","Res"}, 17), ("d4-2", {"Eng","Sales"}, 19), ("d4-3", {"Leg","Sales"}, 17), ("d4-4", {"Eng","Sales"}, 19)],
    5: [("d5-1", {"Fin","Res"}, 11), ("d5-2", {"Eng","Sales"}, 19), ("d5-3", {"Eng","Fin"}, 16), ("d5-4", {"Sales","Res"}, 14)],
    6: [("d6-1", {"Eng","Leg"}, 22), ("d6-2", {"Fin","Sales"}, 11), ("d6-3", {"Eng","Sales"}, 19)],
    7: [("d7-1", {"Eng","Fin"}, 16), ("d7-2", {"Eng","Sales"}, 19), ("d7-3", {"Fin","Leg"}, 14), ("d7-4", {"Fin","Res"}, 11)],
    8: [("d8-1", {"Fin","Sales"}, 11), ("d8-2", {"Leg","Sales"}, 17), ("d8-3", {"Eng","Fin"}, 16)],
    9: [("d9-1", {"Leg","Res"}, 17), ("d9-2", {"Eng","Res"}, 19), ("d9-3", {"Fin","Res"}, 11), ("d9-4", {"Fin","Res"}, 11)],
}

leaked_on = {5: "d5-2", 6: "d6-3", 7: "d7-2"}
for dept in ["Eng", "Sales"]:
    print(f"=== {dept} ===")
    already_leaked = set()
    for d in range(1, 10):
        elig = []
        for dd in range(max(1, d-2), d+1):
            for did, ds, n in docs[dd]:
                if dept in ds and did not in already_leaked:
                    elig.append((did, d-dd, n))
        print(f"Day {d}: n_elig={len(elig)}, min_r={min((x[2] for x in elig), default=0)}, max_r={max((x[2] for x in elig), default=0)} -> {elig}")
        if d in leaked_on:
            already_leaked.add(leaked_on[d])
'
